"Записываем числа в столбик: единицы под единицами, десятки под десятками. Начинаем с единиц.": "Сандарды бағанға жазамыз: бірліктерді бірліктердің астына, ондықтарды ондықтардың астына. Бірліктерден бастаймыз.",
"У числа 100 нет ни десятков, ни единиц. Разменяем сотню: 100 = 9 десятков и 10 единиц.": "100 санында ондық та, бірлік те жоқ. Жүздікті ауыстырамыз: 100 = 9 ондық және 10 бірлік.",
"Это однозначное число: в нём только единицы.": "Бұл бір таңбалы сан: онда тек бірліктер бар.",
"100 — это 10 десятков. Перед ним 99. После него — 101.": "100 — бұл 10 ондық. Одан бұрын 99. Одан кейін 101.",
"Хорошо! Можно идти дальше или посмотреть остальное.": "Жақсы! Әрі қарай жүруге немесе қалғанын қарауға болады.",
"Хорошо! Числа идут по порядку: каждое следующее на 1 больше.": "Жақсы! Сандар ретімен келеді: әрбір келесісі 1-ге артық.",
"10 единиц — это 1 десяток! Собираем их в палочку.": "10 бірлік — бұл 1 ондық! Оларды таяқшаға жинаймыз.",
"Десяток разменяли на 10 единиц и одну убрали.": "Бір ондықты 10 бірлікке ауыстырып, біреуін алып тастадық.",
"Все числа собраны! 🌟": "Барлық сан жиналды! 🌟",
"Нажми «+ сотня»": "«+ жүздік» түймесін бас",
"10 сотен — это 1000, тысяча! Одна сотня — это 10 десятков, то есть 100.": "10 жүздік — бұл 1000, мың! Бір жүздік — бұл 10 ондық, яғни 100.",
"Тысяча! Дальше считать сотнями не нужно.": "Мың! Жүздіктеп әрі санаудың қажеті жоқ.",
"Выбери, как считать 👆": "Қалай санайтыныңды таңда 👆",
"по 3": "3-теп",
"по 4": "4-теп",
"по 5": "5-теп",
"Все три счёта посмотрели!": "Үш санаудың бәрін қарадың!",
"Нажми на число 👆": "Санды бас 👆",
"Один кружок остался без пары.": "Бір дөңгелек жұпсыз қалды.",
"Все кружки встали в пары, лишнего нет.": "Барлық дөңгелек жұп-жұп болып тұрды, артығы жоқ.",
"Замечаешь? Чётные числа оканчиваются на 0, 2, 4, 6, 8. Нечётные — на 1, 3, 5, 7, 9.": "Байқадың ба? Жұп сандар 0, 2, 4, 6, 8-мен аяқталады. Тақ сандар — 1, 3, 5, 7, 9-бен.",
"Нужно посмотреть несколько чётных и несколько нечётных чисел.": "Бірнеше жұп және бірнеше тақ санды қарау керек.",
"На сколько равных частей делим?": "Неше тең бөлікке бөлеміз?",
"Хорошо! Равные части — это когда в каждой одинаково.": "Жақсы! Тең бөліктер — әрқайсысында бірдей болғанда.",
"Попробуй ещё несколько делений.": "Тағы бірнеше бөлуді байқап көр.",
"Алгоритм понятен! Теперь потренируемся сами.": "Алгоритм түсінікті! Енді өзіміз жаттығамыз.",
"Следующий шаг →": "Келесі қадам →",
"групп": "топ",
"в каждой по": "әр топта",
"Это умножение:": "Бұл көбейту:",
"Видишь? Умножение — это сложение одинаковых слагаемых.": "Көрдің бе? Көбейту — бірдей қосылғыштарды қосу.",
"Это прямой угол": "Бұл тік бұрыш",
"Это острый угол": "Бұл сүйір бұрыш",
"Это тупой угол": "Бұл доғал бұрыш",
"Прямой угол — как угол листа бумаги, угольника или квадрата.": "Тік бұрыш — қағаз парағының, сызғыш-үшбұрыштың немесе шаршының бұрышы сияқты.",
"Острый угол меньше прямого. Он острый, как кончик карандаша.": "Сүйір бұрыш тік бұрыштан кіші. Ол қарындаштың ұшындай өткір.",
"Тупой угол больше прямого. Стороны «раскрылись» шире.": "Доғал бұрыш тік бұрыштан үлкен. Қабырғалары кеңірек «ашылды».",
"Все три вида углов найдены!": "Бұрыштың үш түрі де табылды!",
"Начать заново": "Қайтадан бастау",
"Все чертежи готовы! 🌟": "Барлық сызба дайын! 🌟",
"Не та точка. Пройди путь по шагам от красной точки, считая клетки.": "Дұрыс емес нүкте. Қызыл нүктеден қадамдап жүріп, торкөздерді санап көр.",
"Это не прямой угол. Стороны должны идти по клеточным линиям: одна вдоль, другая поперёк.": "Бұл тік бұрыш емес. Қабырғалар торкөз сызықтары бойымен жүруі керек: бірі бойына, екіншісі көлденең.",
